<script setup lang="ts">
import {ref,watch,onMounted} from 'vue';
import {api,type CmsStatus} from '@/services/api';
import CmsConnectionReport from './CmsConnectionReport.vue';
const base=ref(''),saved=ref(''),busy=ref(''),error=ref(''),message=ref(''),report=ref<CmsStatus|null>(null);
async function load(){busy.value='load';try{const v=await api.cmsStatus();base.value=v.base;saved.value=v.base;report.value=v;}catch(e){error.value=(e as Error).message;}finally{busy.value='';}}
async function run(save=false){if(busy.value)return;busy.value=save?'save':'test';error.value='';message.value='';try{if(save){const v=await api.cms(base.value.trim());saved.value=v.cmsBase;report.value=v.cmsStatus;message.value='内容源地址已保存，即时用于后续请求。检测结果见下方。';}else report.value=await api.checkCms(base.value.trim());}catch(e){const failure=e as Error & {cmsStatus?:CmsStatus};error.value=failure.message;if(failure.cmsStatus)report.value=failure.cmsStatus;}finally{busy.value='';}}
watch(base,()=>{report.value=null;message.value='';error.value='';},{flush:'sync'});onMounted(load);
</script>
<template><view class="cms-settings"><view class="config-card"><view class="card-head"><view><view class="head-title"><text>苹果 CMS 内容源</text><text class="badge live">即时生效</text></view><text class="head-subtitle">通过实际 HTTP 接口读取分类与影片，供手机、平板与 TV 客户端使用</text></view><text class="badge">MacCMS</text></view><view class="card-body"><text v-if="error" class="notice error" role="alert">{{error}}</text><text v-if="message" class="notice success" role="status">{{message}}</text><view class="field-row"><text class="field-label">站点地址</text><view class="field-content"><input v-model="base" :disabled="!!busy" placeholder="https://你的苹果CMS域名" aria-label="苹果CMS站点地址"/><text class="help">填写真实站点地址，后端检查分类、影片列表和响应格式。不是直接填写 MySQL 地址。</text></view></view><view class="active-row"><text>当前内容源</text><text selectable>{{saved||'尚未配置'}}</text></view><view class="card-footer"><text class="muted">检测不会保存地址；保存后立即切换内容源，请查看实际检测结果。</text><view class="actions"><button :disabled="!!busy||!base.trim()" @click="run()">{{busy==='test'?'检测中…':'测试接口'}}</button><button class="primary" :disabled="!!busy||!base.trim()" @click="run(true)">{{busy==='save'?'保存中…':'保存并连接'}}</button></view></view><CmsConnectionReport v-if="report" :report="report" title="内容接口检测明细" :checking="!!busy"/></view></view></view></template>
<style scoped src="../styles/service-forms.css"></style>
